<tr data-tembusan-id="{{ $t->id }}" data-search="{{ strtolower($t->laporanKendala->perihal.' '.($t->laporanKendala->satuan->nama ?? '')) }}" data-prioritas="{{ $t->laporanKendala->prioritas }}"><td>{{ $t->laporanKendala->perihal }}</td><td style="text-align:center"><span class="satuan-pill">{{ $t->laporanKendala->satuan->kode ?? $t->laporanKendala->satuan->nama ?? '-' }}</span></td><td><span class="priority-tag prio-{{ strtolower($t->laporanKendala->prioritas) }}">{{ $t->laporanKendala->prioritas }}</span></td><td style="text-align:center"><span class="status-dot {{ $t->dibaca_at ? 'green' : 'amber' }}">{{ $t->dibaca_at ? 'Sudah dibaca' : 'Belum dibaca' }}</span></td><td style="text-align:center;max-width:220px">@if($t->feedback)<div style="font-size:11px;line-height:1.4;text-align:left;color:var(--text-muted)"><span style="color:var(--gold-bright);font-weight:700">Terkirim:</span> {{ $t->feedback }}</div>@else<details style="text-align:left"><summary style="cursor:pointer;font-size:11px;font-weight:700;color:var(--gold-bright)">Beri Feedback</summary><form method="POST" action="{{ route('laporan-kendala-tembusan.feedback', $t->id) }}" style="margin-top:6px;display:flex;flex-direction:column;gap:6px"><input type="hidden" name="_token" value="{{ csrf_token() }}"><input type="hidden" name="_method" value="PATCH"><textarea name="feedback" required maxlength="5000" placeholder="Tulis catatan untuk Kasansi..." style="width:100%;min-height:56px;box-sizing:border-box;resize:vertical;padding:6px 8px;border:1px solid var(--border);border-radius:6px;background:var(--panel-alt);color:var(--text);font:inherit;font-size:11.5px"></textarea><button type="submit" class="detail-btn" style="align-self:flex-end;font-size:11px">Kirim Feedback</button></form></details>@endif</td><td style="text-align:center">{{ $t->laporanKendala->created_at->translatedFormat('d M Y H:i') }}</td><td><div class="review-actions" style="justify-content:center"><button type="button" class="detail-btn" onclick="openReportDetail(this)" data-pengirim="{{ e($t->laporanKendala->satuan->nama ?? '-') }}" data-tujuan="DANPUS (tembusan ke {{ e($satuan->nama) }})" data-perihal="{{ e($t->laporanKendala->perihal) }}" data-prioritas="{{ e($t->laporanKendala->prioritas) }}" data-tanggal="{{ e($t->laporanKendala->created_at->translatedFormat('d M Y H:i')) }}" data-deskripsi="{{ e($t->laporanKendala->deskripsi) }}" data-lampiran="{{ $t->laporanKendala->lampiran_path ? e(asset('storage/'.$t->laporanKendala->lampiran_path)) : '' }}" data-readonly="1" data-readonly-text="Ini laporan tembusan (info/koordinasi) dari {{ e($t->laporanKendala->satuan->nama ?? '-') }} ke DANPUS -- Kasansi menunggu feedback Anda sebelum meneruskannya.">Detail</button>@if(! $t->dibaca_at)<form method="POST" action="{{ route('laporan-kendala-tembusan.baca', $t->id) }}">@csrf @method('PATCH')<button type="submit" class="detail-btn" style="border-color:var(--gold-bright);color:var(--gold-bright)">Tandai Dibaca</button></form>@endif</div></td></tr>
